import { describe, test, expect } from "vitest";
import { produce, produceWithPatches } from "../src/immer";

describe("array reverse/sort regression", () => {
  test("reverse + mutate should not mutate base", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}] as {v: number}[];

    const next = produce(base, (draft) => {
      draft.reverse();
      draft[0].v = 999;
    });

    // next should be [{v: 999}, {v: 2}, {v: 1}] (reversed and first mutated)
    expect(next).toEqual([{v: 999}, {v: 2}, {v: 1}]);

    // base should be untouched
    expect(base).toEqual([{v: 1}, {v: 2}, {v: 3}]);
  });

  test("sort + mutate should not mutate base", () => {
    const base = [{v: 3}, {v: 1}, {v: 2}] as {v: number}[];

    const next = produce(base, (draft) => {
      draft.sort((a, b) => a.v - b.v);
      draft[0].v = 999;
    });

    // next should be [{v: 999}, {v: 2}, {v: 3}] (sorted then first mutated)
    expect(next).toEqual([{v: 999}, {v: 2}, {v: 3}]);

    // base should be untouched
    expect(base).toEqual([{v: 3}, {v: 1}, {v: 2}]);
  });

  test("reverse + mutate should produce correct patches", () => {
    const base = [{v: 1}, {v: 2}, {v: 3}] as {v: number}[];

    const [next, patches] = produceWithPatches(base, (draft) => {
      draft.reverse();
      draft[0].v = 999;
    });

    expect(next).toEqual([{v: 999}, {v: 2}, {v: 1}]);

    // Apply patches manually to base and verify
    let patched = produce(base, (draft) => {
      for (const patch of patches) {
        // Apply each patch
        let target: any = draft;
        for (let i = 0; i < patch.path.length - 1; i++) {
          target = target[patch.path[i]];
        }
        const lastKey = patch.path[patch.path.length - 1];
        if (patch.op === "replace") {
          target[lastKey] = patch.value;
        } else if (patch.op === "add") {
          target[lastKey] = patch.value;
        } else if (patch.op === "remove") {
          delete target[lastKey];
        }
      }
    });

    expect(patched).toEqual([{v: 999}, {v: 2}, {v: 1}]);
  });
});
EOF
